describe('Shopping Cart - Add and Remove Products', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
    cy.login('standard_user', 'secret_sauce');
  });

  it('should add product to cart and update cart badge', () => {
    // Verify initial cart badge is empty
    cy.get('[data-testid="shopping_cart_badge"]').should('contain', '0');

    // Click add to cart button
    cy.get('[data-testid="add-to-cart-sauce-labs-backpack"]').click();

    // Verify cart badge now shows '1'
    cy.get('[data-testid="shopping_cart_badge"]').should('contain', '1');

    // Verify button label changes to 'Remove'
    cy.get('[data-testid="remove-sauce-labs-backpack"]').should('be.visible');
    cy.get('[data-testid="remove-sauce-labs-backpack"]').should('contain', 'Remove');

    // Verify product is still visible in cart
    cy.get('[data-testid="product-name-sauce-labs-backpack"]').should('be.visible');
  });

  it('should remove product from cart and update cart badge', () => {
    // Verify product is in cart
    cy.get('[data-testid="product-name-sauce-labs-backpack"]').should('be.visible');

    // Click remove button
    cy.get('[data-testid="remove-sauce-labs-backpack"]').click();

    // Verify cart badge now shows '0'
    cy.get('[data-testid="shopping_cart_badge"]').should('contain', '0');

    // Verify button label changes to 'Add'
    cy.get('[data-testid="add-to-cart-sauce-labs-backpack"]').should('be.visible');
    cy.get('[data-testid="add-to-cart-sauce-labs-backpack"]').should('contain', 'Add');

    // Verify product is no longer visible in cart
    cy.get('[data-testid="product-name-sauce-labs-backpack"]').should('not.exist');
  });
});
